import React from 'react';
import { motion, AnimatePresence, Reorder } from 'framer-motion';
import { CheckCircle2, Circle, Trash2, Calendar, Tag, GripVertical } from 'lucide-react';

function TaskList({ tasks, toggleComplete, deleteTask, setTasks }) {
  const getPriorityColor = (priority) => {
    switch (priority) {
      case 'High': return 'var(--danger)';
      case 'Medium': return '#ffd700';
      case 'Low': return 'var(--accent-primary)';
      default: return 'var(--text-secondary)';
    }
  };

  return (
    <Reorder.Group
      axis="y"
      values={tasks}
      onReorder={setTasks}
      className="task-list"
    >
      <AnimatePresence mode="popLayout">
        {tasks.length === 0 ? (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9 }}
            className="empty-state"
            key="empty"
          >
            <div className="empty-icon">📂</div>
            <p>No tasks found. Start by adding one above!</p>
          </motion.div>
        ) : (
          tasks.map((task) => (
            <Reorder.Item
              value={task}
              key={task.id}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, scale: 0.9 }}
              whileDrag={{
                scale: 1.05,
                boxShadow: "0 20px 40px rgba(0,0,0,0.4)",
                zIndex: 10
              }}
              className="task-item"
            >
              <div className="task-content">
                <div className="drag-handle">
                  <GripVertical size={18} color="var(--text-secondary)" />
                </div>
                <button
                  className="checkbox-btn"
                  onClick={() => toggleComplete(task.id)}
                  style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}
                >
                  {task.completed ? (
                    <CheckCircle2 size={24} color="var(--accent-primary)" />
                  ) : (
                    <Circle size={24} color="var(--text-secondary)" />
                  )}
                </button>
                <div className="task-info">
                  <span className={`task-text${task.completed ? ' completed' : ''}`}>
                    {task.text}
                  </span>
                  <div className="task-badges">
                    <span className="badge category">
                      <Tag size={12} style={{ marginRight: 4 }} />
                      {task.category}
                    </span>
                    <span
                      className="badge priority"
                      style={{
                        borderColor: getPriorityColor(task.priority),
                        color: getPriorityColor(task.priority),
                        display: 'flex',
                        alignItems: 'center'
                      }}
                    >
                      <Calendar size={12} style={{ marginRight: 4 }} />
                      {task.priority}
                    </span>
                  </div>
                </div>
              </div>
              <button
                className="delete-btn"
                onClick={() => deleteTask(task.id)}
                aria-label="Delete task"
              >
                <Trash2 size={18} />
              </button>
            </Reorder.Item>
          ))
        )}
      </AnimatePresence>
    </Reorder.Group>
  );
}

export default TaskList;
